import re
from typing import Callable
from src.markers import INJECTION_MARKERS, LEAK_MARKERS

_PHONE = re.compile(r'\b\d{10,}\b')
_EMAIL = re.compile(r'\b[\w.+-]+@[\w-]+\.[\w.-]+\b', re.I)


def _sanitize_input(prompt: str) -> tuple[str, bool]:
    out = prompt
    modified = False
    for marker in INJECTION_MARKERS:
        pattern = re.compile(re.escape(marker), re.I)
        if pattern.search(out):
            out = pattern.sub('[REDACTED]', out)
            modified = True
    return out, modified


def _output_violation(text: str):
    if _PHONE.search(text): return 'pii_in_output'
    if _EMAIL.search(text): return 'pii_in_output'
    lower = text.lower()
    for m in LEAK_MARKERS:
        if m.lower() in lower:
            return 'pii_in_output'
    return None


def safe_complete(prompt: str, llm_call: Callable[[str], str]) -> dict:
    cleaned, modified = _sanitize_input(prompt)
    try:
        out = llm_call(cleaned)
    except Exception:
        return {'text': '', 'blocked': True, 'reason': 'llm_error', 'prompt_was_modified': modified}
    if (reason := _output_violation(out or '')):
        return {'text': '', 'blocked': True, 'reason': reason, 'prompt_was_modified': modified}
    return {'text': out, 'blocked': False, 'reason': None, 'prompt_was_modified': modified}
